from xml.dom import minidom
ns = 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'
doc = minidom.parse('unpacked_quarterly/word/document.xml')

def text_of(r):
    out = []
    for t in r.getElementsByTagNameNS(ns, 't'):
        if t.firstChild and t.firstChild.nodeValue:
            out.append(t.firstChild.nodeValue)
    return ''.join(out)

for i, p in enumerate(doc.getElementsByTagNameNS(ns, 'p')):
    direct_runs = [r for r in p.childNodes if r.nodeType == r.ELEMENT_NODE and r.localName == 'r']
    info = []
    for r in direct_runs:
        rprs = r.getElementsByTagNameNS(ns, 'rPr')
        rprxml = rprs[0].toxml() if rprs else '(no rPr)'
        txt = text_of(r)
        info.append((txt, rprxml))
    if info:
        # Also check bold etc
        bold = any(r.getElementsByTagNameNS(ns, 'b') for r in direct_runs)
        print(f'--- P{i}')
        for txt, rpr in info:
            print(f'    text={txt!r}')
            print(f'      rPr={rpr}')
EOF
